-- Script SQL para adicionar o campo show_live na tabela zoom_meetings\n-- Este campo permite ao admin controlar manualmente qual reuni\u00e3o exibir ao vivo\n\n-- Adicionar coluna show_live\nALTER TABLE zoom_meetings \nADD COLUMN show_live TINYINT(1) DEFAULT 0 \nAFTER is_active,\nADD INDEX idx_show_live (show_live);\n\n-- Comentar a coluna\nALTER TABLE zoom_meetings \nMODIFY COLUMN show_live TINYINT(1) DEFAULT 0 COMMENT 'Se 1, esta reuni\u00e3o ser\u00e1 exibida ao vivo na p\u00e1gina';\n\n-- Verificar estrutura atualizada\nDESCRIBE zoom_meetings;\n"}]